<template><div class="app-container"><el-form :model="query" :inline="true" v-show="showSearch"><el-form-item label="昵称"><el-input v-model="query.nickname" clearable @keyup.enter="getList" /></el-form-item><el-form-item label="手机号"><el-input v-model="query.phone" clearable @keyup.enter="getList" /></el-form-item><el-form-item label="状态"><el-select v-model="query.status" clearable><el-option label="正常" value="0" /><el-option label="禁用" value="1" /></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="getList">查询</el-button><el-button icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form><el-row :gutter="10" class="mb8"><el-col :span="1.5"><el-button type="warning" plain icon="Download" v-hasPermi="['shop:member:export']" @click="handleExport">导出</el-button></el-col><right-toolbar v-model:showSearch="showSearch" @queryTable="getList" /></el-row><el-table v-loading="loading" :data="members"><el-table-column prop="memberId" label="会员ID" width="100" /><el-table-column prop="avatarUrl" label="头像" width="72"><template #default="scope"><image-preview :src="scope.row.avatarUrl" :width="36" :height="36" /></template></el-table-column><el-table-column prop="nickname" label="昵称" min-width="150" /><el-table-column prop="phone" label="手机号" width="140" /><el-table-column prop="status" label="状态" width="90"><template #default="scope"><el-tag :type="scope.row.status==='0'?'success':'info'">{{scope.row.status==='0'?'正常':'禁用'}}</el-tag></template></el-table-column><el-table-column prop="createTime" label="注册时间" width="180"><template #default="scope">{{parseTime(scope.row.createTime)}}</template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="scope"><el-button link type="primary" v-hasPermi="['shop:member:sensitive']" @click="showAddresses(scope.row)">地址</el-button><el-button link type="primary" v-hasPermi="['shop:member:status']" @click="toggle(scope.row)">{{scope.row.status==='0'?'禁用':'启用'}}</el-button></template></el-table-column></el-table><pagination v-show="total>0" v-model:total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="getList" /><el-dialog v-model="addressOpen" title="收货地址" width="680px"><el-table :data="addresses"><el-table-column prop="receiverName" label="收货人" /><el-table-column prop="receiverPhone" label="手机号" /><el-table-column label="地址" min-width="300"><template #default="scope">{{scope.row.provinceName}}{{scope.row.cityName}}{{scope.row.districtName}}{{scope.row.detailAddress}}</template></el-table-column></el-table></el-dialog></div></template>
<script setup name="ShopMember">import { reactive,ref,getCurrentInstance } from 'vue';import {changeMemberStatus,listMember,listMemberAddresses} from '@/api/shop/member';const {proxy}=getCurrentInstance(),loading=ref(false),showSearch=ref(true),members=ref([]),total=ref(0),addressOpen=ref(false),addresses=ref([]),query=reactive({pageNum:1,pageSize:10,nickname:undefined,phone:undefined,status:undefined});function getList(){loading.value=true;listMember(query).then(r=>{members.value=r.rows;total.value=r.total}).finally(()=>loading.value=false)}function reset(){Object.assign(query,{pageNum:1,nickname:undefined,phone:undefined,status:undefined});getList()}function showAddresses(row){listMemberAddresses(row.memberId).then(r=>{addresses.value=r.data;addressOpen.value=true})}function toggle(row){const status=row.status==='0'?'1':'0';proxy.$modal.confirm(`确认${status==='0'?'启用':'禁用'}会员“${row.nickname}”？`).then(()=>changeMemberStatus(row.memberId,status)).then(()=>{proxy.$modal.msgSuccess('操作成功');getList()}).catch(()=>{})}function handleExport(){proxy.download('shop/member/export',{...query},`member_${new Date().getTime()}.xlsx`)}getList()</script>
